const DEFAULT_CAPABILITIES = {
    usesMemberId: false,
    usesAccountId: false,
    requiresMasterKey: false,
    requires2FA: false,
    auditAlways: false,
};
export function listSystemDataClassificationProfiles() {
    return Object.values(systemDataClassificationProfiles).sort((left, right) => left.label.localeCompare(right.label));
}
export function resolveSystemDataClassificationDeclaration(declaration) {
    if (!declaration) {
        return undefined;
    }
    const profile = declaration.profile ? systemDataClassificationProfiles[declaration.profile] : undefined;
    const overrides = declaration.overrides ?? {};
    const areas = overrides.areas ?? declaration.areas ?? profile?.areas ?? [];
    const noteParts = [profile?.description, declaration.note].filter(Boolean);
    return {
        profile: profile?.key ?? null,
        profileLabel: profile?.label ?? null,
        areas,
        usesMemberId: overrides.usesMemberId ?? declaration.usesMemberId ?? profile?.usesMemberId ?? DEFAULT_CAPABILITIES.usesMemberId,
        usesAccountId: overrides.usesAccountId ?? declaration.usesAccountId ?? profile?.usesAccountId ?? DEFAULT_CAPABILITIES.usesAccountId,
        requiresMasterKey: overrides.requiresMasterKey ?? declaration.requiresMasterKey ?? profile?.requiresMasterKey ?? DEFAULT_CAPABILITIES.requiresMasterKey,
        requires2FA: overrides.requires2FA ?? declaration.requires2FA ?? profile?.requires2FA ?? DEFAULT_CAPABILITIES.requires2FA,
        auditAlways: overrides.auditAlways ?? declaration.auditAlways ?? profile?.auditAlways ?? DEFAULT_CAPABILITIES.auditAlways,
        dsgvoRelevant: overrides.dsgvoRelevant ?? declaration.dsgvoRelevant ?? profile?.dsgvoRelevant ?? false,
        owner: declaration.owner ?? null,
        note: noteParts.length > 0 ? noteParts.join("\n") : null,
        reviewStatus: declaration.reviewStatus,
        reviewedAt: declaration.reviewedAt ?? null,
        reviewedBy: declaration.reviewedBy ?? null,
    };
}
